#!/usr/bin/env python3
"""Keep one copy of each agent skill and sub-agent, generated by one Spec Kit version.

Subcommands:
  check
      CI check (Repository tools job). Fails when the Spec Kit versions recorded in .specify/
      disagree, an integration other than Codex is installed or default, a file listed in an
      integration manifest is missing or differs from its recorded hash, a shell script under
      .specify/ lost its executable bit (Spec Kit 1.2.0 `integration switch` drops it), a skill
      registered by an extension is missing from .agents/skills/, a tool entry point is not the
      expected symlink, .github/skills/ exists again, a sub-agent source or
      agent-definitions/agents.toml is invalid, an old-layout .github/agents/<name>.md exists,
      .claude/agents is a symlink or file, or Git tracks any file in the sub-agent tool folders
      (the Git check is skipped outside a Git repository), or a lefthook-generated post-checkout,
      post-merge or post-rewrite hook is left in the Git hooks directory (core.hooksPath is
      respected). `lefthook install` does not delete hooks removed from the config, and such a hook
      runs the checked-out branch's lefthook.yml; the error prints the `rm -f` to run. It fails
      only on a machine that has the files, so CI and fresh clones pass.
      The three folders are git-ignored as a whole (.gitignore), so check passes without the
      generated files, and it does not depend on which tools a developer generates.
  sync [--tool {claude,copilot,codex}]...
      Generates .github/agents/<name>.agent.md, .claude/agents/<name>.md and
      .codex/agents/<name>.toml (git-ignored, one set per developer machine) from
      agent-definitions/<name>.md and the model and reasoning effort that
      agent-definitions/agents.toml sets per tool, and removes generated files without a source
      agent. The tools come from the repeatable --tool flag, else from the comma-separated Git
      config `agent-setup.tools` (for example `git config agent-setup.tools copilot`), else all
      tools. Generated files of the tools not selected are removed; hand-written files (without
      the generated marker) are never touched by sync, but the folders are git-ignored, so Git may
      delete such files on checkout; keep personal agents in your user-level folder (for example
      ~/.claude/agents/). It also removes the now-empty agents folders of the tools not selected
      (and .codex/ when empty) and creates folders only for the selected tools.

  setup
      Interactive (npm run setup-agents): asks which coding agents you use (numbers or names),
      shows the current choice as the default (Enter keeps it; all tools when none is set), saves
      it with `git config --local agent-setup.tools` and runs sync for those tools. It refuses
      without a terminal; use `git config agent-setup.tools <tools>` and `sync` there. A plain
      `sync` with no --tool and no config prints a hint to run it, but only when it changed
      something, so repeated runs stay quiet.

Run from the repository root.
"""

import argparse
import hashlib
import json
import os
import subprocess
import sys
import tomllib
from pathlib import Path, PurePosixPath

SPECIFY_DIR = Path(".specify")
# The only integration: it generates the Spec Kit skills into .agents/skills/, which all tools read.
INTEGRATION = "codex"
SKILLS_DIR = Path(".agents/skills")
# Hand-edited, tool-neutral sub-agent sources and the model and effort they get per tool.
DEFINITIONS_DIR = Path("agent-definitions")
AGENT_CONFIG = DEFINITIONS_DIR / "agents.toml"
# Generated sub-agent files, one folder per tool.
COPILOT_AGENTS_DIR = Path(".github/agents")
CLAUDE_AGENTS_DIR = Path(".claude/agents")
CODEX_AGENTS_DIR = Path(".codex/agents")
TOOLS = ("claude", "copilot", "codex")
SETTINGS = ("model", "effort")
# Keys that agents.toml owns, so a source must not set them.
CONFIG_KEYS = ("model", "effort", "reasoning-effort")
REMOVED_SKILLS_DIR = Path(".github/skills")
# Reasoning effort levels that Claude Code, Copilot and Codex all accept.
EFFORT_LEVELS = ("low", "medium", "high", "xhigh", "max")
# Each tool entry point is a symlink, so the files themselves exist once.
SYMLINKS = {
    Path(".claude/skills"): "../.agents/skills",
}


def read_json(path):
    return json.loads(path.read_text(encoding="utf-8"))


def pinned_version(root):
    return read_json(root / SPECIFY_DIR / "integration.json")["version"]


def manifests(root):
    return sorted((root / SPECIFY_DIR / "integrations").glob("*.manifest.json"))


def find_version_mismatches(root, pinned):
    """Return 'path: version' for each recorded Spec Kit version that is not the pinned one."""
    recorded = {
        SPECIFY_DIR / "init-options.json": read_json(root / SPECIFY_DIR / "init-options.json")[
            "speckit_version"
        ]
    }
    for manifest in manifests(root):
        recorded[manifest.relative_to(root)] = read_json(manifest)["version"]
    return [f"{path}: {version}" for path, version in recorded.items() if version != pinned]


def find_integration_problems(root):
    """Return problems when an integration other than the single expected one is installed."""
    state = read_json(root / SPECIFY_DIR / "integration.json")
    problems = []
    if state.get("installed_integrations") != [INTEGRATION]:
        problems.append(
            f"{SPECIFY_DIR / 'integration.json'}: installed integrations are "
            f"{state.get('installed_integrations')}, expected only {INTEGRATION!r} "
            "(remove others with `scripts/specify.sh integration uninstall <key>`)"
        )
    if state.get("default_integration") != INTEGRATION:
        problems.append(
            f"{SPECIFY_DIR / 'integration.json'}: default integration is "
            f"{state.get('default_integration')!r}, expected {INTEGRATION!r}"
        )
    return problems


def find_modified_generated_files(root):
    """Return manifest-listed files that are missing or differ from their recorded SHA-256."""
    problems = []
    for manifest in manifests(root):
        for path, expected in read_json(manifest)["files"].items():
            file = root / path
            if not file.is_file():
                problems.append(f"{path}: missing (listed in {manifest.name})")
            elif hashlib.sha256(file.read_bytes()).hexdigest() != expected:
                problems.append(
                    f"{path}: edited by hand or generated by another Spec Kit version "
                    f"(listed in {manifest.name})"
                )
    return problems


def shipped_scripts(root):
    """Return the shell scripts the skills run: Spec Kit's own and each extension's scripts/.

    Ignored folders such as .specify/extensions/.cache/ are left out, so a local check agrees
    with CI.
    """
    specify = root / SPECIFY_DIR
    scripts = set((specify / "scripts").rglob("*.sh"))
    scripts.update(specify.glob("extensions/*/scripts/**/*.sh"))
    return sorted(
        file
        for file in scripts
        if not any(part.startswith(".") for part in file.relative_to(specify).parts)
    )


def find_non_executable_scripts(root):
    """Return Spec Kit shell scripts without the executable bit; the skills run them directly."""
    problems = []
    for file in shipped_scripts(root):
        if not file.stat().st_mode & 0o111:
            path = file.relative_to(root)
            problems.append(f"{path}: not executable (run `chmod +x {path}`)")
    return problems


def find_missing_extension_skills(root):
    """Return skills that an installed extension registered but that are not in .agents/skills/."""
    registry = root / SPECIFY_DIR / "extensions" / ".registry"
    if not registry.is_file():
        return []
    problems = []
    for name, extension in sorted(read_json(registry)["extensions"].items()):
        for skill in extension.get("registered_skills", []):
            if not (root / SKILLS_DIR / skill / "SKILL.md").is_file():
                problems.append(
                    f"{SKILLS_DIR / skill}: missing (registered by the {name} extension)"
                )
    return problems


def find_layout_problems(root):
    problems = []
    for link, target in SYMLINKS.items():
        path = root / link
        if not path.is_symlink():
            problems.append(
                f"{link}: must be a symlink to {target} "
                "(on Windows, work in WSL or enable core.symlinks)"
            )
            continue
        actual = path.readlink().as_posix()
        if actual != target:
            problems.append(f"{link}: points to {actual}, expected {target}")
    removed = root / REMOVED_SKILLS_DIR
    if removed.exists() or removed.is_symlink():
        problems.append(
            f"{REMOVED_SKILLS_DIR}: must not exist; skills live only in {SKILLS_DIR} "
            "(Copilot reads it directly)"
        )
    return problems


def read_frontmatter(path):
    """Return a Markdown file's top-level frontmatter 'key: value' pairs and the keys that
    continue on indented lines (nested keys, list items or a wrapped value)."""
    lines = path.read_text(encoding="utf-8").splitlines()
    if not lines or lines[0] != "---":
        raise ValueError("missing frontmatter")
    fields, continued = {}, set()
    key = None
    for line in lines[1:]:
        if line == "---":
            return fields, continued
        if line.startswith((" ", "\t")):
            if key:
                continued.add(key)
            continue
        name, separator, value = line.partition(":")
        if separator and not name.startswith(("-", "#")):
            key = name.strip()
            fields[key] = value.strip()
    raise ValueError("unterminated frontmatter")


def toml_string(value):
    # JSON string escapes are a subset of TOML basic string escapes.
    return json.dumps(value, ensure_ascii=False)


def plain_value(value):
    """True for a one-line string that YAML reads back unchanged as a plain scalar."""
    return (
        isinstance(value, str)
        and value != ""
        and value == value.strip()
        and "\n" not in value
        and "\r" not in value
        and not value.startswith(('"', "'", ">", "|", "[", "{", "&", "*", "!", "%", "@", "`", "#"))
        and ": " not in value
        and " #" not in value
    )


def read_agent(root, agent):
    """Return (source path, frontmatter fields) of a sub-agent source, or raise ValueError."""
    source = agent.relative_to(root).as_posix()
    try:
        fields, continued = read_frontmatter(agent)
    except ValueError as error:
        raise ValueError(f"{source}: {error}") from error
    for key in ("name", "description"):
        # Only plain one-line values are copied: a wrapped value would be cut to its first line,
        # and quoted or block YAML would be copied verbatim.
        if key in continued or fields.get(key, "").startswith(('"', "'", ">", "|")):
            raise ValueError(f"{source}: write '{key}' as a plain one-line value")
        if not fields.get(key):
            raise ValueError(f"{source}: frontmatter needs '{key}'")
    if fields["name"] != agent.stem:
        raise ValueError(f"{source}: 'name' must match the file name ({agent.stem})")
    for key in CONFIG_KEYS:
        if key in fields:
            raise ValueError(f"{source}: remove '{key}'; set it in {AGENT_CONFIG.as_posix()}")
    return source, fields


def read_agent_config(root, names):
    """Return ({agent name: {tool: {setting: value}}}, [problems]) from agents.toml.

    `names` are the agents that have a source file.
    """
    where = AGENT_CONFIG.as_posix()
    file = root / AGENT_CONFIG
    if not file.is_file():
        return {}, [f"{where}: missing"]
    try:
        data = tomllib.loads(file.read_text(encoding="utf-8"))
    except tomllib.TOMLDecodeError as error:
        return {}, [f"{where}: invalid TOML ({error})"]
    agents, profiles = data.get("agents", {}), data.get("profiles", {})
    if not isinstance(agents, dict) or not isinstance(profiles, dict):
        return {}, [f"{where}: [agents] and [profiles] must be tables"]
    problems = []
    for name in sorted(set(names) - set(agents)):
        problems.append(f"{where}: [agents] has no entry for '{name}'")
    for name in sorted(set(agents) - set(names)):
        source = (DEFINITIONS_DIR / f"{name}.md").as_posix()
        problems.append(f"{where}: [agents] '{name}' has no {source}")
    named = set()
    for name, profile in sorted(agents.items()):
        if not isinstance(profile, str):
            problems.append(f"{where}: [agents] '{name}' must name a profile (string)")
        elif profile not in profiles:
            problems.append(f"{where}: [agents] '{name}' uses unknown profile {profile!r}")
        else:
            named.add(profile)
    for profile in sorted(set(profiles) - named):
        problems.append(f"{where}: profile '{profile}' is not used by any agent")
    for profile, tools in sorted(profiles.items()):
        if not isinstance(tools, dict):
            problems.append(f"{where}: profile '{profile}' must be a table of tools")
            continue
        for tool, settings in sorted(tools.items()):
            if tool not in TOOLS:
                problems.append(
                    f"{where}: profile '{profile}' has unknown tool '{tool}' "
                    f"(expected {', '.join(TOOLS)})"
                )
                continue
            if not isinstance(settings, dict):
                problems.append(f"{where}: profile '{profile}' {tool} must be a table")
                continue
            for key, value in sorted(settings.items()):
                if key not in SETTINGS:
                    problems.append(
                        f"{where}: profile '{profile}' {tool} has unknown key '{key}' "
                        f"(expected {', '.join(SETTINGS)})"
                    )
                elif key == "effort" and value not in EFFORT_LEVELS:
                    problems.append(
                        f"{where}: profile '{profile}' {tool} effort must be one of "
                        f"{', '.join(EFFORT_LEVELS)}"
                    )
                elif key == "model" and not plain_value(value):
                    problems.append(
                        f"{where}: profile '{profile}' {tool} model must be a non-empty "
                        "plain one-line string"
                    )
    if problems:
        return {}, problems
    return {
        name: {tool: profiles[profile].get(tool, {}) for tool in TOOLS}
        for name, profile in agents.items()
    }, []


GENERATED_MARKER = "# Generated by `python3 scripts/agent_setup.py sync`"


def generated_comment(source):
    return (
        f"{GENERATED_MARKER[2:]}; do not edit. "
        f"Source of truth: {source} (instructions) and "
        f"{AGENT_CONFIG.as_posix()} (model and effort per tool). "
        "Edit those, then run sync."
    )


def markdown_agent(agent, source, settings, keys):
    """Return the source with the generated comment and settings added to its frontmatter.

    `keys` maps each setting (model, effort) to the key this tool reads it from.
    """
    lines = agent.read_text(encoding="utf-8").splitlines(keepends=True)
    end = next(i for i in range(1, len(lines)) if lines[i].rstrip("\r\n") == "---")
    added = [f"{key}: {settings[name]}\n" for name, key in keys.items() if name in settings]
    comment = f"# {generated_comment(source)}\n"
    return "".join([lines[0], comment, *lines[1:end], *added, *lines[end:]])


def codex_pointer(source, fields, settings):
    """Return the .codex/agents/<name>.toml content for an agent-definitions/<name>.md file."""
    instructions = (
        f"Read `{source}` from the repository root and follow it in full. It defines this agent;\n"
        "ignore its frontmatter, which is for other tools. "
        "This file already sets what Codex uses.\n"
    )
    return (
        f"# {generated_comment(source)}\n"
        f"name = {toml_string(fields['name'])}\n"
        f"description = {toml_string(fields['description'])}\n"
        + (f"model = {toml_string(settings['model'])}\n" if "model" in settings else "")
        + (
            f"model_reasoning_effort = {toml_string(settings['effort'])}\n"
            if "effort" in settings
            else ""
        )
        + f'developer_instructions = """\n{instructions}"""\n'
    )


def expected_agent_files(root):
    """Return ({generated file path: content}, [problems]) for the agents in agent-definitions/."""
    agents, problems = {}, []
    for agent in sorted((root / DEFINITIONS_DIR).glob("*.md")):
        try:
            agents[agent.stem] = (agent, *read_agent(root, agent))
        except ValueError as error:
            problems.append(str(error))
    settings, config_problems = read_agent_config(
        root, [p.stem for p in (root / DEFINITIONS_DIR).glob("*.md")]
    )
    problems += config_problems
    problems += old_layout_problems(root)
    problems += claude_agents_problem(root)
    if problems:
        return {}, problems
    expected = {}
    for name, (agent, source, fields) in agents.items():
        tools = settings[name]
        expected[COPILOT_AGENTS_DIR / f"{name}.agent.md"] = markdown_agent(
            agent, source, tools["copilot"], {"model": "model", "effort": "reasoning-effort"}
        )
        expected[CLAUDE_AGENTS_DIR / f"{name}.md"] = markdown_agent(
            agent, source, tools["claude"], {"model": "model", "effort": "effort"}
        )
        expected[CODEX_AGENTS_DIR / f"{name}.toml"] = codex_pointer(source, fields, tools["codex"])
    return expected, []


def old_layout_problems(root):
    """Return a problem for each .github/agents/<name>.md, where sources used to live."""
    return [
        f"{file.relative_to(root).as_posix()}: move it to {DEFINITIONS_DIR.as_posix()}/"
        f"{file.name} (.github/agents/ holds only generated *.agent.md files)"
        for file in sorted((root / COPILOT_AGENTS_DIR).glob("*.md"))
        if file.is_file() and not file.name.endswith(".agent.md")
    ]


def claude_agents_problem(root):
    """Return the problem when .claude/agents is a symlink (the old layout) or a file."""
    path = root / CLAUDE_AGENTS_DIR
    if path.is_symlink():
        what = "is a symlink"
    elif path.exists() and not path.is_dir():
        what = "is not a directory"
    else:
        return []
    return [
        f"{CLAUDE_AGENTS_DIR}: {what}; must be a directory of generated files "
        "(remove it, then run `python3 scripts/agent_setup.py sync`)"
    ]


# The files each tool folder holds that sync generates.
GENERATED_PATTERNS = (
    (COPILOT_AGENTS_DIR, "*.agent.md"),
    (CLAUDE_AGENTS_DIR, "*.md"),
    (CODEX_AGENTS_DIR, "*.toml"),
)


def is_generated(file):
    """True if the file carries the generated marker.

    The marker is the first line of TOML and the line after `---` in Markdown.
    """
    lines = file.read_text(encoding="utf-8", errors="replace").splitlines()
    index = 1 if file.suffix == ".md" else 0
    return len(lines) > index and lines[index].startswith(GENERATED_MARKER)


def stale_generated_files(root, expected):
    """Marked generated files without a source; unmarked (hand-written) files are ignored."""
    for directory, pattern in GENERATED_PATTERNS:
        for file in sorted((root / directory).glob(pattern)):
            if file.is_file() and file.relative_to(root) not in expected and is_generated(file):
                yield file


def run_git(root, *args):
    """Run git in root with messages in English; raises OSError when git cannot be started."""
    return subprocess.run(
        ["git", "-C", str(root), *args],
        capture_output=True,
        text=True,
        env={**os.environ, "LC_ALL": "C"},
    )


def git_failure(result):
    reason = result.stderr.strip() or f"git exited with {result.returncode}"
    return f"could not check Git state: {reason}"


def inside_work_tree(root):
    """Return (inside, error): whether root is in a Git work tree, or why that is unknown."""
    try:
        result = run_git(root, "rev-parse", "--is-inside-work-tree")
    except OSError as error:
        return False, f"could not check Git state: {error}"
    if result.returncode != 0:
        if "not a git repository" in result.stderr.lower():
            return False, None
        return False, git_failure(result)
    return result.stdout.strip() == "true", None


def find_git_problems(root):
    """Return a problem for each file Git tracks in a sub-agent tool folder.

    Nothing is checked outside a Git work tree; other Git failures are reported.
    """
    inside, error = inside_work_tree(root)
    if error:
        return [f"{error}; fix Git or the environment and rerun the check"]
    if not inside:
        return []
    try:
        folders = [directory.as_posix() for directory, _ in GENERATED_PATTERNS]
        listed = run_git(root, "ls-files", "-z", "--", *folders)
    except OSError as error:
        return [f"could not check Git state: {error}"]
    if listed.returncode != 0:
        return [git_failure(listed)]
    return tracked_folder_problems([name for name in listed.stdout.split("\0") if name])


# lefthook once installed these; `lefthook install` does not delete hooks removed from the config.
# lefthook runs the lefthook.yml of the checked-out tree, so a leftover one executes a branch's code
# on every checkout, merge or rebase.
REMOVED_HOOKS = ("post-checkout", "post-merge", "post-rewrite")


def hooks_directory(root):
    """Return the directory Git runs hooks from (core.hooksPath, else the Git directory's hooks)."""
    configured = run_git(root, "config", "--get", "core.hooksPath")
    if configured.returncode == 0 and configured.stdout.strip():
        return (Path(root) / Path(configured.stdout.strip()).expanduser()).resolve()
    located = run_git(root, "rev-parse", "--git-path", "hooks")
    if located.returncode != 0:
        return None
    return (Path(root) / located.stdout.strip()).resolve()


def find_leftover_hooks(root):
    """Return a problem naming the lefthook-generated post-* hooks that still exist locally.

    Only hooks that mention lefthook count, so other tools' hooks (for example Git LFS) are left
    alone. Nothing exists in CI or a fresh clone, so the check passes there. Git failures are
    reported by find_git_problems, not here.
    """
    try:
        inside, error = inside_work_tree(root)
        directory = hooks_directory(root) if inside and not error else None
    except OSError:
        return []
    if directory is None:
        return []
    found = []
    for name in REMOVED_HOOKS:
        path = directory / name
        try:
            if path.is_file() and "lefthook" in path.read_text(encoding="utf-8", errors="replace").lower():
                found.append(path)
        except OSError:
            continue
    if not found:
        return []
    base = Path(root).resolve()

    def shown(path):
        try:
            return path.relative_to(base).as_posix()
        except ValueError:
            return str(path)

    paths = " ".join(shown(directory / name) for name in REMOVED_HOOKS)
    return [
        f"leftover lefthook hook(s) {', '.join(shown(path) for path in found)}: lefthook runs the "
        "lefthook.yml of whatever branch is checked out, so they execute that branch's code on "
        f"checkout, merge and rebase; remove them with `rm -f {paths}`"
    ]


def tracked_folder_problems(tracked):
    """Return a problem for each tracked file under a sub-agent tool folder.

    The folders are git-ignored as a whole, so any file in them must not be tracked. A tracked
    .claude/agents symlink is reported by claude_agents_problem, not here.
    """
    folders = [PurePosixPath(directory.as_posix()) for directory, _ in GENERATED_PATTERNS]
    return [
        f"{name}: files in the sub-agent tool folders are not versioned (put shared "
        f"agents in {DEFINITIONS_DIR.as_posix()}/); run `git rm --cached {name}`"
        for name in tracked
        if any(folder in PurePosixPath(name).parents for folder in folders)
    ]


def split_agent_file_problems(root):
    """Return (source problems, repository state problems) for the sub-agent files.

    Source problems are in the sub-agent sources, agents.toml and the old layouts; state problems
    are files Git tracks in the tool folders.

    The generated files are git-ignored and written by `sync` on each machine, so a missing, stale
    or orphaned one is not a problem; a tracked one is.
    """
    _, problems = expected_agent_files(root)
    if problems:
        return problems, []
    return [], find_git_problems(root) + find_leftover_hooks(root)


def find_agent_file_problems(root):
    """Return problems in the sub-agent sources, agents.toml, the old layouts and tracked tool-folder
    files."""
    return [problem for group in split_agent_file_problems(root) for problem in group]


def split_problems(root):
    """Return (problems that need the restore hint, problems that explain themselves)."""
    pinned = pinned_version(root)
    source_problems, state_problems = split_agent_file_problems(root)
    hinted = (
        [f"Spec Kit version is not {pinned}: {m}" for m in find_version_mismatches(root, pinned)]
        + find_integration_problems(root)
        + find_modified_generated_files(root)
        + find_non_executable_scripts(root)
        + find_missing_extension_skills(root)
        + find_layout_problems(root)
        + source_problems
    )
    return hinted, state_problems


def find_problems(root):
    return [problem for group in split_problems(root) for problem in group]


def run_check(root):
    hinted, state_problems = split_problems(root)
    for problem in hinted + state_problems:
        print(f"::error::{problem}")
    if hinted:
        print(
            "Restore generated Spec Kit files with git or regenerate them with "
            "`scripts/specify.sh integration upgrade codex --force`; "
            "fix sub-agent sources in agent-definitions/ and rerun the check."
        )
    if hinted or state_problems:
        return 1
    print(
        f"Spec Kit {pinned_version(root)}: versions, generated files and agent layout "
        "are consistent."
    )
    return 0


CONFIG_ORIGIN = "git config agent-setup.tools"


def configured_names(root):
    """Return the tool names in Git config agent-setup.tools (empty when unset or no Git)."""
    try:
        result = subprocess.run(
            ["git", "-C", str(root), "config", "--get", "agent-setup.tools"],
            capture_output=True,
            text=True,
        )
    except OSError:
        return []
    configured = result.stdout.strip() if result.returncode == 0 else ""
    return [name.strip() for name in configured.split(",") if name.strip()]


def selected_tools(root, flags):
    """Return (tools, error): the --tool flags, else Git config agent-setup.tools, else all."""
    if flags:
        names, origin = list(flags), "--tool"
    else:
        names, origin = configured_names(root), CONFIG_ORIGIN
    unknown = [name for name in names if name not in TOOLS]
    if unknown:
        return None, (
            f"{origin}: unknown tool {', '.join(repr(name) for name in unknown)} "
            f"(expected {', '.join(TOOLS)})"
        )
    return (set(names) if names else set(TOOLS)), None


def tool_of(path):
    """Return the tool whose folder holds the generated file path."""
    folders = (COPILOT_AGENTS_DIR, CLAUDE_AGENTS_DIR, CODEX_AGENTS_DIR)
    tools = ("copilot", "claude", "codex")
    return next(tool for tool, folder in zip(tools, folders) if folder in path.parents)


def remove_empty_dir(path):
    """rmdir semantics: remove the folder only if it exists and is empty."""
    try:
        path.rmdir()
    except OSError:
        return False
    return True


def remove_empty_agent_folders(root, directory):
    """Remove an unselected tool's empty agents folder, then its parent if agents-only (.codex)."""
    removed = False
    if remove_empty_dir(root / directory):
        print(f"removed {directory.as_posix()}/")
        removed = True
        parent = directory.parent
        if parent in AGENTS_ONLY_PARENTS and remove_empty_dir(root / parent):
            print(f"removed {parent.as_posix()}/")
    return removed


# Parents that exist only for agents; .github and .claude also hold workflows and skills.
AGENTS_ONLY_PARENTS = (CODEX_AGENTS_DIR.parent,)


def run_sync(root, tools=None):
    selected, error = selected_tools(root, tools)
    if error:
        print(f"::error::{error}")
        return 1
    expected, problems = expected_agent_files(root)
    if problems:
        for problem in problems:
            print(f"::error::{problem}")
        return 1
    changed = False
    wanted = {path: content for path, content in expected.items() if tool_of(path) in selected}
    for file in list(stale_generated_files(root, wanted)):
        file.unlink()
        changed = True
        print(f"removed {file.relative_to(root)}")
    for directory, _ in GENERATED_PATTERNS:
        if tool_of(directory / "x") in selected:
            (root / directory).mkdir(parents=True, exist_ok=True)
        else:
            changed |= remove_empty_agent_folders(root, directory)
    for path, content in wanted.items():
        file = root / path
        if not file.is_file() or file.read_text(encoding="utf-8") != content:
            file.write_text(content, encoding="utf-8")
            changed = True
            print(f"wrote {path}")
    if changed and not tools and not configured_names(root):
        print(ALL_TOOLS_HINT)
    return 0


# Menu order of `setup`; the number a developer types is the position here.
MENU = (("copilot", "GitHub Copilot"), ("claude", "Claude Code"), ("codex", "Codex"))
ALL_TOOLS_HINT = (
    "Generated sub-agents for all tools (Claude Code, GitHub Copilot, Codex). "
    "Optional: run npm run setup-agents to keep only the ones you use; "
    "run it again whenever you change coding agents."
)
RERUN_HINT = (
    "Run npm run setup-agents again whenever you change coding agents, "
    "to generate the files for the new ones."
)


def parse_choice(answer):
    """Return the tools named by menu numbers or tool names, in TOOLS order; None if invalid."""
    chosen = set()
    for token in answer.replace(",", " ").split():
        if token.isascii() and token.isdigit() and 1 <= int(token) <= len(MENU):
            chosen.add(MENU[int(token) - 1][0])
        elif token.lower() in TOOLS:
            chosen.add(token.lower())
        else:
            return None
    return [tool for tool in TOOLS if tool in chosen] or None


def ask_tools(ask, current=()):
    """Show the menu and return the chosen tools in TOOLS order, or None when cancelled.

    `current` is the saved choice: Enter keeps it, and all tools when it is empty. The caller
    checks for a terminal; this only calls `ask`.
    """
    current = [name for name in TOOLS if name in current]
    default = current or list(TOOLS)
    print("Which coding agents do you use? (comma-separated numbers)")
    for number, (_, label) in enumerate(MENU, start=1):
        print(f"  {number}) {label}")
    print(f"Current choice: {', '.join(current) if current else 'none (all tools are generated)'}")
    while True:
        try:
            answer = ask("Choice [Enter keeps current]: ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\nCancelled; nothing changed.")
            return None
        chosen = default if not answer else parse_choice(answer)
        if chosen:
            return chosen
        print("Enter numbers 1-3 or tool names (copilot, claude, codex), separated by commas.")


def save_tools(root, tools):
    """Save the tools in Git config agent-setup.tools; print the error and return False on failure."""
    result = subprocess.run(
        ["git", "-C", str(root), "config", "--local", "agent-setup.tools", ",".join(tools)],
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        print(f"::error::could not save the choice: {result.stderr.strip()}")
        return False
    return True


def run_setup(root, ask=input, isatty=sys.stdin.isatty):
    """Ask which tools the developer uses, save it in Git config and sync those tools."""
    if not isatty():
        print(
            "::error::setup is interactive and needs a terminal. Run "
            "`git config agent-setup.tools <tools>` (comma-separated: "
            f"{', '.join(TOOLS)}) and then `python3 scripts/agent_setup.py sync` instead."
        )
        return 1
    current = [name for name in TOOLS if name in configured_names(root)]
    chosen = ask_tools(ask, current)
    if chosen is None:
        return 1
    if not save_tools(root, chosen):
        return 1
    print(f"Saved: git config agent-setup.tools {','.join(chosen)}")
    code = run_sync(root, chosen)
    if code == 0:
        print(RERUN_HINT)
    return code


def main():
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    subparsers = parser.add_subparsers(dest="command", required=True)
    subparsers.add_parser("check").set_defaults(run=lambda root, args: run_check(root))
    sync = subparsers.add_parser("sync")
    sync.add_argument(
        "--tool",
        action="append",
        help=f"generate only this tool's files; repeatable ({', '.join(TOOLS)})",
    )
    sync.set_defaults(run=lambda root, args: run_sync(root, args.tool))
    subparsers.add_parser("setup").set_defaults(run=lambda root, args: run_setup(root))
    args = parser.parse_args()
    sys.exit(args.run(Path.cwd(), args))


if __name__ == "__main__":
    main()
